const LEVELS=window.MAGIC_FOREST_LEVELS,PROGRESS=window.MAGIC_FOREST_PROGRESS,KEY='magicForestSaveV2';
let save=JSON.parse(localStorage.getItem(KEY)||'null')||{unlocked:1,stars:{},items:[],crystals:0,sound:true,storySeen:false};
if(save.stars?.[5]&&save.unlocked<6){save.unlocked=6;localStorage.setItem(KEY,JSON.stringify(save))}
const app=document.querySelector('#app');let audio,cancelProfile;document.addEventListener('click',event=>{if(event.target?.id==='cancelProfile')home()});
function playerName(){return save.player?.name?.trim()||'แบมแบม'}
function personalize(value){return String(value).replaceAll('แบมแบม',playerName())}
function applyPlayerCopy(from='แบมแบม'){if(!save.player)return;const visit=value=>{if(Array.isArray(value))return value.forEach(visit);if(value&&typeof value==='object')return Object.keys(value).forEach(k=>{if(typeof value[k]==='string')value[k]=value[k].replaceAll(from,playerName());else visit(value[k])})};visit(LEVELS);visit(window.WORLD_ONE_ENDING);visit(window.WORLD_TWO_ENDING)}
const ITEM_BOOK={
 'เมล็ดแสง':{art:'golden-star.png',note:'เก็บพลังจากประตูเถาวัลย์ ใช้ปลุกสิ่งที่หลับใหล'},
 'เศษผลึกฟ้า':{art:'echo-crystal.png',note:'เศษหัวใจของป่า ส่งเสียงใสเมื่ออยู่ใกล้เวทมนตร์'},
 'ใบปัญญา':{art:'explorer-compass.png',note:'ใบไม้ที่ชี้ทางให้ผู้กล้าซึ่งคิดอย่างรอบคอบ'},
 'หยดน้ำค้างแท้':{art:'moon.png',note:'น้ำค้างจากถ้ำเสียงโกหก ส่องแสงเมื่อได้ยินความจริง'},
 'ผลึกหัวใจชิ้นที่ 1':{art:'adventure-map.png',note:'กุญแจชิ้นแรกสู่หัวใจแห่งป่า และเส้นทางสู่อาณาจักรถัดไป'}
 ,'ศิลาจันทร์คู่':{art:'moon.png',note:'หินสองสีที่รวมแสงเป็นสะพานข้ามทะเลสาบแห่งดวงจันทร์'},
 'แกนคริสตัลสมบูรณ์':{art:'echo-crystal.png',note:'แกนกลางจากคริสตัล 457 ชิ้นที่รอดจากเวทมนตร์ทำลาย'}
 ,'เกล็ดรุ้งแปดสี':{art:'golden-star.png',note:'ประกายจากเกล็ด 56 ชิ้นของปลาสายรุ้งทั้งแปดตัว'}
 ,'ตราประตูใบไม้':{art:'explorer-compass.png',note:'ตราที่เกิดจากใบไม้ทองและเงินรวมกันครบ 445 ใบ'}
 ,'เม็ดทรายแห่งโอเอซิส':{art:'golden-star.png',note:'ทราย 455 กิโลกรัมที่เหลือและช่วยปลุกโอเอซิสกลับคืนมา'}
};
function itemInfo(savedItem){const name=savedItem.replace(/^\S+\s+/,'');return {name,...(ITEM_BOOK[name]||{art:'golden-star.png',note:'ของวิเศษจากการผจญภัย'})}}
function itemArt(savedItem,extra=''){const item=itemInfo(savedItem);return `<img class="item-art ${extra}" src="assets/items/${item.art}" alt="${item.name}">`}
function levelArt(level,extra=''){const files=['level-1-vine-gate.png','level-2-stone-bridge.png','level-3-dancing-mushrooms.png','level-4-crystal-cave.png','level-5-heart-tree.png','level-6-moon-lake.png','level-7-crystal-cave.png','level-8-rainbow-waterfall.png','level-9-leaf-tunnel.png','level-10-magic-desert.png'];const src=files[level.id-1]?`assets/levels/${files[level.id-1]}`:'assets/items/moon.png';return `<img class="level-art ${extra}" src="${src}" alt="${level.title}">`}
function hotspotArt(level,index,extra=''){const files={1:['level-1-red-flowers.png','level-1-blue-flowers.png','level-1-magic-rune.png'],2:['level-2-stone-pile.png','level-2-repaired-bridge.png','level-2-shadow-footprints.png'],3:['level-3-pink-mushrooms.png','level-3-blue-mushrooms.png','level-3-fluffy.png'],4:['level-4-dew-pool.png','level-4-silver-feather.png','level-4-echo.png'],5:['level-5-butterflies.png','level-5-tree-heart.png','level-5-shadow-vines.png','level-5-shadow-crystal.png']};if(files[level.id])return `<img class="hotspot-art ${extra}" src="assets/hotspots/${files[level.id][index]}" alt="">`;return `<span class="hotspot-emoji ${extra}">${level.hotspots[index].icon}</span>`}
function persist(){localStorage.setItem(KEY,JSON.stringify(save))}
function tone(freq=520,d=.12){if(!save.sound)return;audio||=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.07,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+d)}
function topbar(back){return `<header class="topbar">${back?'<button class="icon-btn" data-back aria-label="ย้อนกลับ">‹</button>':''}<div class="brand"><img src="assets/items/golden-star.png" alt=""> ผจญภัยในป่าเวทมนตร์</div><button class="pill collection-pill" data-inventory aria-label="เปิดกระเป๋าของสะสม"><img src="assets/items/adventure-map.png" alt=""> <b>${save.items.length}/${LEVELS.length}</b></button><div class="pill">💎 <b>${save.crystals}</b></div><button class="icon-btn" data-sound aria-label="เปิดหรือปิดเสียง">${save.sound?'🔊':'🔇'}</button></header>`}
function common(backFn=map){document.querySelector('[data-sound]')?.addEventListener('click',e=>{save.sound=!save.sound;persist();e.currentTarget.textContent=save.sound?'🔊':'🔇';tone()});document.querySelector('[data-back]')?.addEventListener('click',backFn);document.querySelectorAll('[data-inventory]').forEach(b=>b.addEventListener('click',showInventory))}
function collectionCard(l){const saved=save.items.find(x=>x.endsWith(l.reward));if(!saved)return `<div class="collection-card locked-item"><div class="item-silhouette">?</div><div><strong>ของวิเศษที่ยังไม่พบ</strong><p>ผ่านตอนที่ ${l.id} เพื่อเปิดเผย</p></div></div>`;const info=itemInfo(saved);return `<div class="collection-card">${itemArt(saved)}<div><strong>${info.name}</strong><p>${info.note}</p></div></div>`}
function collectionWorld(world,title){const levels=LEVELS.filter(l=>(l.world||1)===world),found=levels.filter(l=>save.items.some(x=>x.endsWith(l.reward))).length;return `<section class="collection-world collection-world-${world}"><div class="collection-world-title"><h3>${title}</h3><span>${found}/${levels.length} ชิ้น</span></div><div class="collection-grid">${levels.map(collectionCard).join('')}</div></section>`}
function showInventory(){document.body.insertAdjacentHTML('beforeend',`<div class="collection-modal" role="dialog" aria-modal="true" aria-label="กระเป๋านักผจญภัย"><section class="collection-panel"><button class="collection-close" aria-label="ปิดกระเป๋า">×</button><div class="eyebrow">ของวิเศษจากทุกการผจญภัย</div><h2>กระเป๋านักผจญภัย</h2><p class="collection-summary">ค้นพบแล้ว ${save.items.length} จาก ${LEVELS.length} ชิ้น · ผลึก ${save.crystals} เม็ด</p>${collectionWorld(1,'World 1 · ป่าแห่งตัวเลข')}${collectionWorld(2,'World 2 · เส้นทางสู่อาณาจักรเห็ด')}</section></div>`);const modal=document.querySelector('.collection-modal');modal.querySelector('.collection-close').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};modal.querySelector('.collection-close').focus()}
function characterArt(who,fallback,extra=''){if(who.includes('ชิป')&&who.includes('ฟลัฟฟี่'))return `<span class="character-pair"><img src="assets/characters/chip.png" alt="ชิป"><img src="assets/characters/fluffy.png" alt="ฟลัฟฟี่"></span>`;if(who.includes('แบมแบม')||who.includes(playerName())){const file=save.player?.gender==='girl'?'bambam-girl.png':'bambam.png';return `<img class="character-art ${extra}" src="assets/characters/${file}" alt="${playerName()} นักผจญภัยตัวน้อย">`}if(who.includes('ชิป'))return `<img class="character-art ${extra}" src="assets/characters/chip.png" alt="ชิป กระรอกผู้ช่วยของ${playerName()}">`;if(who.includes('ฟลัฟฟี่'))return `<img class="character-art ${extra}" src="assets/characters/fluffy.png" alt="ฟลัฟฟี่ กระต่ายนักผจญภัย">`;if(who.includes('ต้นไม้'))return `<img class="character-art ${extra}" src="assets/characters/silver-tree.png" alt="ต้นไม้สีเงินผู้พิทักษ์ป่าเวทมนตร์">`;if(who.includes('พ่อมด'))return `<img class="character-art ${extra}" src="assets/characters/shadow-wizard.png" alt="พ่อมดเงาจอมเจ้าเล่ห์">`;if(fallback==='🌙')return `<img class="character-art ${extra}" src="assets/items/moon.png" alt="ดวงจันทร์เวทมนตร์">`;return fallback}
function starRating(stars){return `<span class="rating-stars" aria-label="${stars} ดาว">${Array.from({length:3},(_,i)=>`<img class="${i<stars?'earned':'empty'}" src="assets/items/golden-star.png" alt="">`).join('')}</span>`}
const PROLOGUE=[
 {who:'ผู้เล่า',face:'🌙',text:'ค่ำวันหนึ่ง หลังเสียงระฆังโรงเรียนดัง แบมแบมได้ยินเสียงกระซิบมาจากป่าที่ไม่เคยมีใครกล้าเข้าไป'},
 {who:'แบมแบม',face:'🧒🏻',text:'เสียงนั้น… กำลังนับเลขอยู่หรือเปล่านะ? หนึ่ง… สอง… แล้วทำไมถึงหยุดล่ะ?'},
 {who:'ต้นไม้สีเงิน',face:'🌳',text:'ผู้ที่ได้ยินเสียงของตัวเลข โปรดช่วยข้าด้วย หัวใจแห่งตัวเลขกำลังแตกสลาย!'},
 {who:'ชิป',face:'🐿️',text:'ว้าย! เธอได้ยินจริง ๆ ด้วย ฉันชื่อชิป พ่อมดเงาขโมยผลึกไป ถ้าเราไม่รีบ ป่าทั้งผืนจะลืมวิธีนับ!'},
 {who:'แบมแบม',face:'🧒🏻',text:'งั้นเราไปเอาตัวเลขกลับมากันเถอะ ต่อให้มีหนึ่งร้อยปริศนา ฉันก็ไม่ถอย!'}
];
function profileSetup(){const editing=!!save.player,previousName=playerName();let gender=save.player?.gender||'boy';app.innerHTML=`<section class="profile-screen"><div class="profile-card"><div class="eyebrow">${editing?'โปรไฟล์นักผจญภัย':'สร้างนักผจญภัยของคุณ'}</div><h1>${editing?'ปรับลุคก่อนเดินทางต่อ':'ใครจะได้ยินเสียงตัวเลข?'}</h1><p>เลือกตัวละครและตั้งชื่อ ชื่อนี้จะปรากฏตลอดเรื่องราว</p><div class="character-choice"><button class="${gender==='boy'?'selected':''}" data-gender="boy"><img src="assets/characters/bambam.png" alt="ตัวละครผู้ชาย"><strong>ผู้ชาย</strong></button><button class="${gender==='girl'?'selected':''}" data-gender="girl"><img src="assets/characters/bambam-girl.png" alt="ตัวละครผู้หญิง"><strong>ผู้หญิง</strong></button></div><label class="name-field">ชื่อของนักผจญภัย<input id="playerNameInput" maxlength="12" autocomplete="off" placeholder="เช่น แบมแบม" value="${save.player?.name||''}"></label><div class="name-error" id="nameError" aria-live="polite"></div><div class="profile-actions">${editing?'<button class="secondary" id="cancelProfile">ยกเลิก</button>':''}<button class="primary profile-start" id="savePlayer">${editing?'บันทึกโปรไฟล์':'เริ่มการผจญภัย ✦'}</button></div></div></section>`;document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{gender=b.dataset.gender;document.querySelectorAll('[data-gender]').forEach(x=>x.classList.toggle('selected',x===b))});cancelProfile?.addEventListener('click',home);savePlayer.onclick=()=>{const name=playerNameInput.value.trim().replace(/[<>&"']/g,'');if(!name){nameError.textContent='พิมพ์ชื่อก่อนออกเดินทางนะ';playerNameInput.focus();return}save.player={name:name.slice(0,12),gender};persist();applyPlayerCopy(previousName);home()};playerNameInput.onkeydown=e=>{if(e.key==='Enter')savePlayer.click()};playerNameInput.focus()}
function home(){app.innerHTML=`<section class="screen">${topbar()}<div class="hero"><div class="intro"><div class="eyebrow">บทที่ 1 · เสียงกระซิบจากต้นไม้สีเงิน</div><h1>หัวใจแห่ง<br>ตัวเลขหายไป!</h1><p>เมื่อป่าเริ่มลืมวิธีนับ ${playerName()}ต้องร่วมมือกับชิปและฟลัฟฟี่ ตามหาผลึกที่ถูกพ่อมดเงาขโมยไป</p><div class="actions"><button class="primary" id="start">${save.storySeen?'เดินทางต่อ':'เปิดเรื่องราว'}</button><button class="secondary" id="mapBtn"><img class="button-item" src="assets/items/adventure-map.png" alt=""> แผนที่</button><button class="secondary" id="profileBtn">เปลี่ยนชื่อ/ตัวละคร</button></div><button class="inventory-shelf" data-inventory><span>${save.items.length?'ของวิเศษที่พบแล้ว':'กระเป๋ายังว่างอยู่'}</span><span class="inventory-icons">${save.items.length?save.items.map(x=>itemArt(x)).join(''):'ออกผจญภัยเพื่อค้นหาของวิเศษ ✦'}</span></button></div><div class="companions"><div class="avatar art-avatar hero-player">${characterArt('แบมแบม','🧒🏻')}<small>${playerName()}</small></div><div class="avatar art-avatar">${characterArt('ชิป','🐿️')}<small>ชิป</small></div><div class="avatar art-avatar">${characterArt('ฟลัฟฟี่','🐇')}<small>ฟลัฟฟี่</small></div></div></div></section>`;common();start.onclick=()=>save.storySeen?map():story(PROLOGUE,()=>{save.storySeen=true;persist();map()});mapBtn.onclick=map;profileBtn.onclick=profileSetup}
function story(lines,done,i=0){const line=lines[i];app.innerHTML=`<section class="story-screen">${topbar(true)}<div class="story-stage"><img class="story-magic" src="assets/items/golden-star.png" alt="ประกายเวทมนตร์"><div class="speaker-face">${characterArt(line.who,line.face)}</div><div class="dialogue"><div class="speaker">${personalize(line.who)}</div><p>${personalize(line.text)}</p><button class="primary" id="nextLine">${i===lines.length-1?'ออกเดินทาง':'ต่อไป'}</button></div><div class="skip" id="skip">ข้ามเรื่องราว</div></div></section>`;common(home);nextLine.onclick=()=>{tone(480+i*40);i<lines.length-1?story(lines,done,i+1):done()};skip.onclick=done}
function nextAdventure(){return LEVELS.find(l=>l.id<=save.unlocked&&!save.stars[l.id])||LEVELS[Math.min(save.unlocked,LEVELS.length)-1]||LEVELS[0]}
function stageCard(l,recommendedId){const locked=l.id>save.unlocked,stars=save.stars[l.id]||0,current=l.id===recommendedId;return `<button class="stage world-${l.world||1} ${locked?'locked':''} ${stars?'done':''} ${current?'current':''}" data-level="${l.id}" ${locked?'disabled':''}>${current?'<span class="current-badge">ไปต่อที่นี่ ✦</span>':''}<span class="num">ตอนที่ ${l.id} ${locked?'· 🔒':''}</span>${levelArt(l,'stage-art')}<h2>${l.title}</h2><p>${l.teaser}</p>${starRating(stars)}</button>`}
function worldMap(world,title,subtitle,recommendedId){const levels=LEVELS.filter(l=>(l.world||1)===world),completed=levels.filter(l=>save.stars[l.id]).length,stars=levels.reduce((total,l)=>total+(save.stars[l.id]||0),0),percent=completed/levels.length*100;return `<section class="world-map world-map-${world}"><div class="world-map-head"><div><div class="eyebrow">${subtitle}</div><h2>${title}</h2><p>${completed===levels.length?'พิชิตครบแล้ว! พร้อมออกเดินทางต่อ ✦':`ผ่านแล้ว ${completed} จาก ${levels.length} ตอน`}</p></div><div class="world-progress" aria-label="ผ่าน ${completed} จาก ${levels.length} ตอน"><strong>${completed}/${levels.length}</strong><span>⭐ ${stars}/${levels.length*3}</span><div><i style="width:${percent}%"></i></div></div></div><div class="stage-grid">${levels.map(l=>stageCard(l,recommendedId)).join('')}</div></section>`}
function map(){const next=nextAdventure();app.innerHTML=`<section class="screen">${topbar()}<div class="map-wrap"><div class="map-head"><div><div class="eyebrow">เส้นทางตามหาผลึกทั้งสิบชิ้น</div><h1>แผนที่ป่าเวทมนตร์</h1><p>ทุกโลกมีเรื่องราว ของวิเศษ และพลังตัวเลขแบบใหม่รออยู่</p></div><div class="map-actions"><button class="secondary" id="homeBtn">บ้านต้นไม้</button><button class="primary" id="continueBtn">เล่นตอนที่ ${next.id} ต่อ ▶</button></div></div>${worldMap(1,'World 1 · ป่าแห่งตัวเลข','ผลึกหัวใจชิ้นที่ 1',next.id)}${worldMap(2,'World 2 · เส้นทางสู่อาณาจักรเห็ด','ผลึกหัวใจชิ้นที่ 2',next.id)}</div></section>`;common();homeBtn.onclick=home;continueBtn.onclick=()=>beginLevel(next.id);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>beginLevel(+b.dataset.level))}
function beginLevel(id){const l=LEVELS[id-1];story(l.dialogue,()=>explore(id))}
function explore(id){const l=LEVELS[id-1],found=new Set();app.innerHTML=`<section class="explore ${l.scene}">${topbar(true)}<div class="quest-card"><span>ภารกิจ</span><strong>${l.quest}</strong><div class="clue-progress" aria-live="polite"><div><b id="clueCount">0</b> / ${l.required} เบาะแส</div><span><i id="clueProgressBar"></i></span></div></div><div class="explore-copy"><div class="eyebrow">ตอนที่ ${l.id}</div><h1>${l.title}</h1><p>${l.exploreText}</p></div><div class="hotspots">${l.hotspots.map((h,n)=>`<button class="hotspot ${l.id<=3?'illustrated-hotspot':''}" data-spot="${n}" aria-label="สำรวจ ${h.label}">${hotspotArt(l,n)}<small>${h.label}</small><i class="discovery-spark" aria-hidden="true">✦</i></button>`).join('')}</div><div class="clue-box" id="clue">${characterArt('ชิป','🐿️','clue-character')}<p>ชิป: ลองแตะสิ่งที่น่าสงสัยในฉากดูสิ!</p></div><button class="primary solve-btn" id="solve" disabled>ใช้พลังตัวเลข</button></section>`;common(map);document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>{const n=+b.dataset.spot,h=l.hotspots[n];if(found.has(n))return;found.add(n);b.classList.add('found');clue.innerHTML=`${hotspotArt(l,n,'clue-hotspot-art')}<p><strong>${h.label}</strong><br>${h.clue}</p>`;document.querySelector('#clueCount').textContent=Math.min(found.size,l.required);document.querySelector('#clueProgressBar').style.width=`${Math.min(found.size/l.required,1)*100}%`;tone(560+n*70);if(found.size>=l.required){solve.disabled=false;solve.textContent='ใช้พลังตัวเลข ✦';document.querySelector('.clue-progress').classList.add('complete')}});solve.onclick=()=>play(id)}
function play(id){const l=LEVELS[id-1];let tries=0,digits='',wheels=[6,0,0],echoValue=732,echoSteps=0,wingLight=0,litButterflies=0,crystalValue=915,crystalSteps=0,fishLit=0,rainbowScales=0,leafTotal=189,leafSteps=0,sandTotal=600,sandSteps=0;app.innerHTML=`<section class="play">${topbar(true)}<div class="play-area"><article class="mission"><div class="eyebrow">เวทมนตร์แห่งตัวเลข · ตอนที่ ${l.id}</div><div class="scene-icon">${levelArt(l,'mission-art')}</div><h1>${l.puzzleTitle}</h1><p class="story">${l.story}</p><div class="prompt">${l.prompt}</div><div class="puzzle" id="puzzle"></div><div class="feedback" id="feedback" aria-live="polite"><div class="star-chance">โอกาสรอบนี้ ${starRating(3)}</div></div></article></div></section>`;common(()=>explore(id));const p=document.querySelector('#puzzle'),fb=document.querySelector('#feedback');const check=v=>{tries++;if(String(v)===String(l.answer)){tone(760,.3);finish(l,tries);return true}const possibleStars=PROGRESS.starsForTries(tries+1),hint=tries===1?l.hint1:l.hint2;tone(180,.18);fb.innerHTML=`<div class="hint-card">${characterArt('ชิป','🐿️','hint-chip')}<div><strong>${tries===1?'เกือบแล้ว ลองอีกครั้งนะ!':'ชิปมีคำใบ้เพิ่มให้'}</strong><p>${hint}</p><div class="star-chance">ถ้าตอบครั้งถัดไป จะได้ ${starRating(possibleStars)}</div></div></div>`;navigator.vibrate?.(60);return false};
if(l.type==='drag'){p.innerHTML=l.choices.map(x=>`<button draggable="true" class="tile" data-v="${x}">${x}</button>`).join('')+'<div class="slot" tabindex="0">วงแหวนเวท</div>';const slot=p.querySelector('.slot');p.querySelectorAll('.tile').forEach(t=>{t.ondragstart=e=>e.dataTransfer.setData('text',t.dataset.v);t.onclick=()=>check(t.dataset.v)});slot.ondragover=e=>e.preventDefault();slot.ondrop=e=>{e.preventDefault();check(e.dataTransfer.getData('text'))}}
if(l.type==='digits'){p.innerHTML=`<div class="digit-builder"><div class="slot digit-display" id="display" aria-live="polite">_ _ _</div><small id="digitStatus">เลือกตัวเลขหลักที่ 1 จาก 3</small><div class="digit-keys">${l.choices.map(x=>`<button class="tile" data-v="${x}">${x}</button>`).join('')}</div><div class="digit-actions"><button class="choice" id="backspace" disabled>⌫ ลบหลักล่าสุด</button><button class="choice" id="clear" disabled>ล้างทั้งหมด</button><button class="primary" id="submitDigits" disabled>ส่งพลังตัวเลข ✦</button></div></div>`;const refreshDigits=()=>{display.textContent=digits.padEnd(3,'_').split('').join(' ');digitStatus.textContent=digits.length===3?'ครบ 3 หลักแล้ว ตรวจดูแล้วส่งพลังได้เลย':`เลือกตัวเลขหลักที่ ${digits.length+1} จาก 3`;backspace.disabled=!digits.length;clear.disabled=!digits.length;submitDigits.disabled=digits.length!==3};p.querySelectorAll('.tile').forEach(t=>t.onclick=()=>{if(digits.length<3){digits+=t.dataset.v;tone(420+digits.length*80);refreshDigits()}});backspace.onclick=()=>{digits=digits.slice(0,-1);refreshDigits()};clear.onclick=()=>{digits='';refreshDigits()};submitDigits.onclick=()=>{const answer=digits;if(!check(answer)){digits='';refreshDigits()}}}
if(l.type==='counter'){const labels=['หลักร้อย','หลักสิบ','หลักหน่วย'];p.innerHTML=`<div class="number-wheels">${wheels.map((v,i)=>`<div class="wheel"><small>${labels[i]}</small><button data-wheel="${i}" data-dir="1" aria-label="เพิ่ม${labels[i]}">+</button><strong id="wheel${i}">${v}</strong><button data-wheel="${i}" data-dir="-1" aria-label="ลด${labels[i]}">−</button></div>`).join('')}<div class="wheel-total">พลังรวม <strong id="total">600</strong></div></div><button class="primary" id="cast">ร่ายเวทหยุดเพลง</button>`;document.querySelectorAll('[data-wheel]').forEach(b=>b.onclick=()=>{const i=+b.dataset.wheel,dir=+b.dataset.dir;wheels[i]=(wheels[i]+dir+10)%10;document.querySelector('#wheel'+i).textContent=wheels[i];total.textContent=wheels[0]*100+wheels[1]*10+wheels[2];tone(420+i*90)});cast.onclick=()=>check(wheels[0]*100+wheels[1]*10+wheels[2])}
if(l.id===4){const parts=[{v:200,label:'สองร้อยหยด'},{v:80,label:'แปดสิบหยด'},{v:9,label:'เก้าหยด'}];p.innerHTML=`<div class="echo-cave"><img src="assets/characters/cave-bird.png" alt="นกถ้ำที่ดื่มน้ำค้าง"><div class="echo-pool"><small>น้ำค้างที่ยังส่องแสง</small><strong id="echoTotal">732</strong><span id="echoTrail">เริ่มจาก 732 หยด</span></div></div><div class="echo-stones">${parts.map((part,i)=>`<button class="echo-stone" data-subtract="${part.v}" data-index="${i}"><span>−${part.v}</span><small>${part.label}</small></button>`).join('')}</div><button class="primary" id="revealEcho" disabled>เปิดประตูเสียงจริง</button>`;document.querySelectorAll('[data-subtract]').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('heard');echoValue-=+b.dataset.subtract;echoSteps++;echoTotal.textContent=echoValue;echoTrail.textContent+=` − ${b.dataset.subtract}`;tone(600-echoSteps*80,.22);if(echoSteps===parts.length){revealEcho.disabled=false;fb.textContent='เสียงสะท้อนที่พูดจริงเริ่มเปล่งแสงแล้ว!'}});revealEcho.onclick=()=>check(echoValue)}
if(l.id===5){p.innerHTML=`<div class="boss-stage"><div class="shadow-vines" aria-hidden="true">🕸️</div><div class="wing-meter"><small>พลังแสงจากปีก</small><strong><span id="wingCount">0</span> / 18</strong><div><i id="wingBar"></i></div></div></div><div class="butterfly-swarm">${Array.from({length:9},(_,i)=>`<button class="light-butterfly" data-butterfly="${i}" aria-label="ปลุกผีเสื้อตัวที่ ${i+1}"><img src="assets/characters/light-butterfly.png" alt=""><small>+2 ปีก</small></button>`).join('')}</div><button class="primary final-spell" id="finalSpell" disabled>ปล่อยคาถาแสง 18 ปีก!</button>`;document.querySelectorAll('[data-butterfly]').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('lit');litButterflies++;wingLight+=2;wingCount.textContent=wingLight;wingBar.style.width=`${wingLight/18*100}%`;tone(440+litButterflies*38,.18);if(litButterflies===9){finalSpell.disabled=false;fb.textContent='ผีเสื้อทั้ง 9 ตัวพร้อมแล้ว—ปล่อยพลังจากปีก 18 ข้าง!'}});finalSpell.onclick=()=>check(wingLight)}
if(l.type==='repair'){const shards=[400,50,8];p.innerHTML=`<div class="crystal-repair"><div class="crystal-core"><small>คริสตัลที่ยังสมบูรณ์</small><strong id="crystalTotal">915</strong><span id="crystalTrail">เริ่มจาก 915 ชิ้น</span></div><div class="crystal-meter"><i id="crystalBar"></i></div></div><div class="crystal-shards">${shards.map((v,i)=>`<button data-shard="${i}" data-value="${v}" ${i?'disabled':''}><span>−${v}</span><small>${['หลักร้อย','หลักสิบ','หลักหน่วย'][i]}</small></button>`).join('')}</div><button class="primary" id="repairCrystal" disabled>รวมแสงคริสตัลที่เหลือ</button>`;const shardButtons=[...document.querySelectorAll('[data-shard]')];shardButtons.forEach((b,i)=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('placed');crystalValue-=+b.dataset.value;crystalSteps++;crystalTotal.textContent=crystalValue;crystalTrail.textContent+=` − ${b.dataset.value}`;crystalBar.style.width=`${crystalSteps/3*100}%`;tone(480+crystalSteps*90,.2);if(shardButtons[i+1])shardButtons[i+1].disabled=false;else{repairCrystal.disabled=false;fb.textContent='เหลือคริสตัลสมบูรณ์ 457 ชิ้น—รวมแสงได้เลย!'}});repairCrystal.onclick=()=>check(crystalValue)}
if(l.type==='fish'){p.innerHTML=`<div class="rainbow-score"><small>พลังเกล็ดสายรุ้ง</small><strong><span id="scaleCount">0</span> / 56</strong><div><i id="rainbowBar"></i></div></div><div class="fish-school">${Array.from({length:8},(_,i)=>`<button data-fish="${i}" aria-label="ปลุกปลาสายรุ้งตัวที่ ${i+1}"><span>🐟</span><small>+7</small></button>`).join('')}</div><button class="primary" id="releaseRainbow" disabled>ปล่อยพลังเกล็ด 56 ชิ้น!</button>`;document.querySelectorAll('[data-fish]').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('lit');fishLit++;rainbowScales+=7;scaleCount.textContent=rainbowScales;rainbowBar.style.width=`${rainbowScales/56*100}%`;tone(420+fishLit*45,.16);if(fishLit===8){releaseRainbow.disabled=false;fb.textContent='ปลาทั้ง 8 ตัวพร้อมแล้ว—เกล็ด 56 ชิ้นกำลังส่องแสง!'}});releaseRainbow.onclick=()=>check(rainbowScales)}
if(l.type==='leaves'){const bundles=[200,50,6];p.innerHTML=`<div class="leaf-total"><small>ใบไม้ทอง 189 + ใบไม้เงิน</small><strong id="leafCount">189</strong><span id="leafTrail">เริ่มจาก 189 ใบ</span></div><div class="leaf-bundles">${bundles.map((v,i)=>`<button data-leaf="${i}" data-value="${v}" ${i?'disabled':''}><span>${i?'🍃':'🍁'}</span><b>+${v}</b><small>${['มัดใหญ่','มัดกลาง','มัดเล็ก'][i]}</small></button>`).join('')}</div><button class="primary" id="openLeafGate" disabled>เปิดประตูด้วยใบไม้ 445 ใบ</button>`;const leafButtons=[...document.querySelectorAll('[data-leaf]')];leafButtons.forEach((b,i)=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('woven');leafTotal+=+b.dataset.value;leafSteps++;leafCount.textContent=leafTotal;leafTrail.textContent+=` + ${b.dataset.value}`;tone(460+leafSteps*100,.2);if(leafButtons[i+1])leafButtons[i+1].disabled=false;else{openLeafGate.disabled=false;fb.textContent='ใบไม้ทองและเงินรวมกันครบ 445 ใบแล้ว!'}});openLeafGate.onclick=()=>check(leafTotal)}
if(l.type==='sand'){const scoops=[100,40,5];p.innerHTML=`<div class="sand-scale"><small>ทรายเวทมนตร์ที่เหลือ</small><strong id="sandCount">600</strong><span id="sandTrail">เริ่มจาก 600 กิโลกรัม</span><div><i id="sandBar"></i></div></div><div class="sand-scoops">${scoops.map((v,i)=>`<button data-sand="${i}" data-value="${v}" ${i?'disabled':''}><span>⌛</span><b>−${v}</b><small>${['ถ้วยใหญ่','ถ้วยกลาง','ถ้วยเล็ก'][i]}</small></button>`).join('')}</div><button class="primary" id="restoreOasis" disabled>คืนพลังทราย 455 กิโลกรัม</button>`;const sandButtons=[...document.querySelectorAll('[data-sand]')];sandButtons.forEach((b,i)=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('poured');sandTotal-=+b.dataset.value;sandSteps++;sandCount.textContent=sandTotal;sandTrail.textContent+=` − ${b.dataset.value}`;sandBar.style.width=`${sandSteps/3*100}%`;tone(520+sandSteps*80,.2);if(sandButtons[i+1])sandButtons[i+1].disabled=false;else{restoreOasis.disabled=false;fb.textContent='ทรายเหลือ 455 กิโลกรัม—คืนพลังให้อโอเอซิสได้เลย!'}});restoreOasis.onclick=()=>check(sandTotal)}
if(l.type==='choice'&&l.id!==4&&l.id!==5){p.innerHTML=l.choices.map(x=>`<button class="choice" data-v="${x}">${x}</button>`).join('');p.querySelectorAll('.choice').forEach(c=>c.onclick=()=>check(c.dataset.v))}}
function finish(l,tries){const result=PROGRESS.completeLevel(save,l,tries,LEVELS.length),{runStars,previousStars,bestStars,savedItem,isNewItem,isRecord}=result;save=result.nextSave;persist();const lootText=isNewItem?`ได้รับ “${l.reward}” · 💎 +10`:`มี “${l.reward}” อยู่แล้ว · ไม่ได้รับผลึกซ้ำ`,starText=!previousStars?`ผ่านครั้งแรก · ได้ ${runStars} ดาว`:isRecord?`สถิติใหม่! ${previousStars} → ${runStars} ดาว`:`รอบนี้ ${runStars} ดาว · สถิติสูงสุด ${bestStars} ดาว`,nextText=l.id===5?'ดูตอนจบ World 1':l.id===10?'ดูตอนจบ World 2':l.id===LEVELS.length?'กลับสู่แผนที่':'เดินทางต่อ';app.insertAdjacentHTML('beforeend',`<div class="reward"><div class="reward-card"><div class="reward-burst reward-art">${itemArt(savedItem)}</div><div class="reward-score"><small>ดาวรอบนี้</small>${starRating(runStars)}<strong class="reward-record ${isRecord?'new-record':''}">${starText}</strong></div><h2>${l.successTitle}</h2><p>${l.success}</p><div class="loot">${lootText}</div><div class="reward-actions"><button class="secondary" id="retry">เล่นอีกครั้ง ↻</button><button class="primary" id="next">${nextText}</button></div></div></div>`);retry.onclick=()=>explore(l.id);next.onclick=()=>l.id===5?story(window.WORLD_ONE_ENDING,map):l.id===10?story(window.WORLD_TWO_ENDING,map):map()}
applyPlayerCopy();save.player?home():profileSetup();
